import sys
import heapq

def dijkstra(graph, start):
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def min_time_to_reach_n(n, m, railways):
    # Build the graph for railways
    railway_graph = {i: {} for i in range(1, n + 1)}
    for u, v in railways:
        railway_graph[u][v] = 1
        railway_graph[v][u] = 1

    # Build the graph for roads (complement of railway graph)
    road_graph = {i: {} for i in range(1, n + 1)}
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            if j not in railway_graph[i]:
                road_graph[i][j] = 1
                road_graph[j][i] = 1

    # Calculate shortest paths from 1 to n for both railway and road graphs
    railway_distances = dijkstra(railway_graph, 1)
    road_distances = dijkstra(road_graph, 1)

    if railway_distances[n] == float('inf') or road_distances[n] == float('inf'):
        return -1

    min_time = float('inf')

    # Try all possible arrival times for the train at intermediate nodes
    for i in range(1, n):
        if i in railway_distances and i in road_distances:
            train_time = railway_distances[i]
            bus_time = road_distances[i]

            # Calculate the time for the bus to reach n after the train arrives at i
            if train_time <= bus_time:
                bus_time += road_distances[n] - road_distances[i]

            # Calculate the time for the train to reach n after the bus arrives at i
            if bus_time <= train_time:
                train_time += railway_distances[n] - railway_distances[i]

            min_time = min(min_time, max(train_time, bus_time))

    return min_time

